#!/usr/bin/env python3
"""Compute the CSX-313 Q1 report-confirmed landslide-tsunami source model."""

from __future__ import annotations

import json
import re
from pathlib import Path


TASK_ID = "CSX-313_Q1"
PACKAGE_ID = "CSX-313"
TARGET_FAMILY = "landslide_tsunami_process_model"

SOURCE_LOAD_SCALE = 40000.0
RUNUP_SCENARIO_MULTIPLIER = 1.15

ANSWER_LABEL = "source_dominated_landslide_tsunami_report_confirmed"
FALLBACK_LABEL = "mixed_or_underconstrained_fjord_hazard"



REASONING_DEPTH = {'evidence_weighting': 'The report-confirmed rockslide mass, runup, fjord source setting, glacier-retreat context, and deep-water context are decisive; auxiliary products are not needed for the source-dominance label.', 'counterfactual_rejection': 'A weather, exposure, or generic remote-sensing explanation fails because the source mass and extreme runup already establish the landslide-tsunami mechanism.', 'uncertainty_or_scale_caveat': 'The 15 percent runup scenario is a sensitivity test, not a prediction of a second observed event.'}


def attach_reasoning_depth(result):
    reasoning = dict(REASONING_DEPTH)
    primary = result.get("primary_gt")
    if isinstance(primary, dict):
        primary["reasoning_depth"] = reasoning
    guidance = result.get("answer_guidance")
    if isinstance(guidance, dict):
        guidance["reasoning_depth"] = reasoning
    key_values = result.get("key_values")
    if isinstance(key_values, dict):
        key_values["reasoning_depth"] = reasoning
    rubric = result.get("rubric")
    if isinstance(rubric, dict):
        criteria = rubric.get("criteria")
        if isinstance(criteria, list) and criteria:
            addition = " Full credit also requires the `reasoning_depth` object to identify decisive evidence, reject the main tempting simplification, and state a bounded uncertainty or scale caveat."
            last = criteria[-1]
            desc = last.get("description", "")
            if addition.strip() not in desc:
                last["description"] = (desc.rstrip() + addition).strip()
    return result

def read_json(path: Path) -> dict:
    return json.loads(path.read_text(encoding="utf-8-sig"))


def read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8-sig", errors="replace")


def clip(value: float, lower: float = 0.0, upper: float = 1.0) -> float:
    return max(lower, min(upper, float(value)))


def rounded(value: float, digits: int = 2) -> float:
    return round(float(value), digits)


def package_dir() -> Path:
    task_dir = Path(__file__).resolve().parent
    repo_root = task_dir.parents[2]
    return repo_root / "event_packages" / "standard_event_packages" / "packages" / PACKAGE_ID


def html_plaintext(html: str) -> str:
    text = re.sub(r"<[^>]+>", " ", html)
    return re.sub(r"\s+", " ", text).strip()


def extract_float(pattern: str, text: str) -> float:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"Could not extract numeric value with pattern: {pattern}")
    return float(match.group(1).replace(",", ""))


def build_result() -> dict:
    root = package_dir()

    rel_event_report = "data/event_reports/event_reports_001_Locked_package_evidence_report.html"
    rel_event_anchor = (
        "data/event_reports/event_reports_004_Locked_event_anchor_"
        "Taan_Fiord_glacier-adjacent_landslide_tsunami.json"
    )
    rel_event = "metadata/event.json"
    rel_files = "metadata/files.csv"
    rel_glims = "data/event_catalogs/event_catalogs_002_GLIMS_glacier_database_and_RGI_outlines.html"

    event = read_json(root / rel_event)
    anchor = read_json(root / rel_event_anchor)
    report_text = html_plaintext(read_text(root / rel_event_report))

    mass_million_tons = extract_float(r"sent\s+([0-9,.]+)\s+million tons of rock", report_text)
    runup_m = extract_float(r"as high as\s+([0-9,.]+)\s*m", report_text)

    report_lower = report_text.lower()
    report_mechanism_terms = {
        "fjord_landslide_source": "landslide" in report_lower and "taan fiord" in report_lower,
        "rock_mass_reported": mass_million_tons > 0,
        "tsunami_runup_reported": runup_m > 0,
        "glacier_retreat_context": "glacial retreat" in report_lower and "unstable slopes" in report_lower,
        "deep_water_context": "deep water" in report_lower,
    }
    report_mechanism_completeness = sum(report_mechanism_terms.values()) / len(report_mechanism_terms)
    glacier_retreat_context_flag = int(
        report_mechanism_terms["glacier_retreat_context"] and report_mechanism_terms["deep_water_context"]
    )

    source_runup_load = mass_million_tons * runup_m
    source_power_norm = clip(source_runup_load / SOURCE_LOAD_SCALE)
    process_dominance_index = 100.0 * (
        0.65 * source_power_norm
        + 0.25 * report_mechanism_completeness
        + 0.10 * glacier_retreat_context_flag
    )

    scenario_runup_m = runup_m * RUNUP_SCENARIO_MULTIPLIER
    scenario_source_power_norm = clip((mass_million_tons * scenario_runup_m) / SOURCE_LOAD_SCALE)
    scenario_process_dominance_index = 100.0 * (
        0.65 * scenario_source_power_norm
        + 0.25 * report_mechanism_completeness
        + 0.10 * glacier_retreat_context_flag
    )

    classification = (
        ANSWER_LABEL
        if (
            source_power_norm >= 0.75
            and report_mechanism_completeness >= 0.80
            and glacier_retreat_context_flag == 1
        )
        else FALLBACK_LABEL
    )

    event_window = f"{anchor['temporal_window']['start_date']} to {anchor['temporal_window']['end_date']}"
    location = f"{anchor['spatial_window']['location_text']}, {anchor['spatial_window']['country_or_region']}"

    primary_gt = {
        "source_paths": {
            "event_report": [rel_event_report, rel_event_anchor],
            "metadata_or_catalog_context": [rel_event, rel_files, rel_glims],
        },
        "process_model": {
            "event_window": event_window,
            "location": location,
            "mechanism_chain": [
                "recent glacier retreat exposed unstable slopes",
                "deep fjord water extended beneath slope margins",
                "a 180 million ton rockslide entered Taan Fiord",
                "impulsive displacement generated a tsunami with 193 m maximum runup",
                "the source mechanics dominate the monitoring priority",
            ],
            "classification": classification,
        },
        "computed_metrics": {
            "mass_million_tons": rounded(mass_million_tons, 1),
            "runup_m": rounded(runup_m, 1),
            "source_runup_load_million_ton_m": rounded(source_runup_load, 2),
            "source_power_norm": rounded(source_power_norm, 3),
            "report_mechanism_terms": report_mechanism_terms,
            "report_mechanism_completeness": rounded(report_mechanism_completeness, 3),
            "glacier_retreat_context_flag": glacier_retreat_context_flag,
            "process_dominance_index": rounded(process_dominance_index, 2),
        },
        "scenario_analysis": {
            "runup_increase_percent": 15.0,
            "scenario_runup_m": rounded(scenario_runup_m, 2),
            "scenario_source_power_norm": rounded(scenario_source_power_norm, 3),
            "scenario_process_dominance_index": rounded(scenario_process_dominance_index, 2),
            "scenario_delta_index": rounded(scenario_process_dominance_index - process_dominance_index, 2),
        },
        "scientific_use_notes": {
            "decisive_evidence": (
                "The event report supplies the source mechanism, mass, runup, timing, "
                "and retreat/deep-water fjord context."
            ),
            "weak_context": (
                "Auxiliary precipitation, remote-sensing, exposure, and geocoding slices are not "
                "used for this source-dominance score; the report mechanics are sufficient."
            ),
            "interpretive_consequence": (
                "The model emphasizes impulsive landslide-tsunami generation and monitoring "
                "sensitivity in deglaciating fjords rather than a rainfall-driven, image-product, "
                "or population-exposure-dominated disaster process."
            ),
        },
        "final_interpretation": (
            "A very large rockslide entering a recently deglaciated deep-water fjord is the dominant "
            "process; the report-confirmed source mass and runup support a source-driven monitoring "
            "priority, and a modest runup-coupling increase would materially raise the index."
        ),
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": PACKAGE_ID,
        "task_type": "structured_reasoning",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "hybrid",
        "difficulty_level": "L4",
        "event": {
            "package_id": event["package_id"],
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": event_window,
            "location": location,
        },
        "primary_gt": primary_gt,
        "key_values": {
            "mass_million_tons": mass_million_tons,
            "runup_m": runup_m,
            "source_runup_load_million_ton_m": source_runup_load,
            "source_power_norm": source_power_norm,
            "report_mechanism_terms": report_mechanism_terms,
            "report_mechanism_completeness": report_mechanism_completeness,
            "glacier_retreat_context_flag": glacier_retreat_context_flag,
        },
        "formulae": {
            "source_power_norm": "clip((mass_million_tons * runup_m) / 40000, 0, 1)",
            "report_mechanism_completeness": "supported report mechanism terms / 5",
            "process_dominance_index": (
                "100 * (0.65 * source_power_norm + 0.25 * report_mechanism_completeness "
                "+ 0.10 * glacier_retreat_context_flag)"
            ),
            "scenario": "increase only runup by 15 percent and recompute source_power_norm and process_dominance_index",
        },
        "tolerances": {
            "source_runup_load_million_ton_m": {"absolute_tolerance": 0.05, "units": "million ton m"},
            "source_power_norm": {"absolute_tolerance": 0.001, "units": "unitless"},
            "report_mechanism_completeness": {"absolute_tolerance": 0.001, "units": "unitless"},
            "process_dominance_index": {"absolute_tolerance": 0.02, "units": "points"},
            "scenario_runup_m": {"absolute_tolerance": 0.01, "units": "m"},
            "scenario_process_dominance_index": {"absolute_tolerance": 0.02, "units": "points"},
            "scenario_delta_index": {"absolute_tolerance": 0.02, "units": "points"},
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "self_directed_package_discovery_and_citations",
                    "points": 3,
                    "description": (
                        "Finds the relevant event report, event anchor or metadata, and optional catalog context "
                        "without exact filenames in the prompt, and cites package-relative paths."
                    ),
                    "partial_credit": "Award 1-2 points for incomplete but relevant citations.",
                },
                {
                    "name": "event_mechanism_reconstruction",
                    "points": 4,
                    "description": (
                        "Correctly identifies location, 17 October 2015 window, retreat/deep-water slope "
                        "conditioning, rockslide entry into the fjord, and tsunami runup process."
                    ),
                    "partial_credit": "Award partial credit for partially correct mechanism chains.",
                },
                {
                    "name": "source_load_calculations",
                    "points": 4,
                    "description": (
                        "Extracts 180 million tons and 193 m; computes source load 34740.0 and "
                        "source_power_norm 0.869 within tolerance."
                    ),
                    "partial_credit": "Award partial credit for correct extraction with arithmetic or rounding mistakes.",
                },
                {
                    "name": "report_mechanism_support",
                    "points": 3,
                    "description": (
                        "Correctly evaluates the five report mechanism terms, reports mechanism completeness 1.000, "
                        "and sets glacier_retreat_context_flag = 1."
                    ),
                    "partial_credit": "Award partial credit for missing one report term or the glacier flag.",
                },
                {
                    "name": "process_index_and_classification",
                    "points": 3,
                    "description": (
                        "Computes process_dominance_index = 91.45 and returns "
                        "source_dominated_landslide_tsunami_report_confirmed using all rule conditions."
                    ),
                    "partial_credit": (
                        "Award partial credit for the right class with a flawed index, or the right index "
                        "with incomplete rule logic."
                    ),
                },
                {
                    "name": "scenario_reasoning",
                    "points": 2,
                    "description": (
                        "Applies the 15 percent runup-only perturbation and reports 221.95 m, 0.999, "
                        "99.92, and 8.47 within tolerance, with fjord-sensitivity interpretation."
                    ),
                    "partial_credit": "Award partial credit for one or two correct scenario values.",
                },
                {
                    "name": "structured_scientific_answer_quality",
                    "points": 1,
                    "description": (
                        "Returns exactly the requested top-level JSON keys, keeps interpretation concise, "
                        "and avoids unsupported casualty, damage, auxiliary-product, or outside-source claims."
                    ),
                    "partial_credit": "No partial credit unless the structure is effectively equivalent.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [rel_event_report, rel_event_anchor, rel_event, rel_files, rel_glims],
            "notes": (
                "MINOR cleanup removed non-Alaska precipitation, remote-sensing, exposure, and geocoding "
                "products from the scoring path; the GT now relies on the report-confirmed source mechanics."
            ),
        },
    }


def main() -> None:
    output = build_result()
    attach_reasoning_depth(output)
    out_path = Path(__file__).resolve().parent / "computed_gt.json"
    out_path.write_text(json.dumps(output, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
